{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Lurtotecan, a polar polycyclic heterocycle, had absolute oral bioavailability of only 11.3% ± 5.2 in patients; with a high assay-transfer score (0.8986), this supports that a highly polar, ionizable polycyclic dicarboxylate like the query is likely to be below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Dronedarone absolute oral bioavailability was only 4% in fasted humans (transfer 0.8759), providing a high-transfer low-F anchor that reinforces the low-bioavailability direction despite different physicochemical drivers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Eliglustat showed a simulated absolute oral bioavailability of 0.086 (transfer 0.7997), another high-transfer low-F example supporting the low prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ofloxacin has >95% absolute oral bioavailability in healthy subjects and the highest transfer score (0.9504), but its single carboxylate plus basic piperazine and fluorine are not shared by the query, which has two carboxylates and no basic center; this high-F evidence is mechanistically weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C43"],
      "claim": "Norfloxacin, the closest structural relative with an N-ethyl pyridinone carboxylate core, has absolute F around 35% in healthy subjects (transfer 0.7974), still above 20%; however, the query's additional carboxylate and absence of the piperazine base would be expected to substantially lower absorption.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Bumetanide, an acidic sulfonamide carboxylate, has absolute F of 0.72-0.96 (transfer 0.8698), showing that acidic drugs can be well absorbed; but the query is much more polar with two fully ionized carboxylates and no lipophilic balance.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Methyldopa, a very polar zwitterion, has absolute F of 42 ± 16% (transfer 0.6231), but its absorption is transporter-mediated; no active-uptake evidence exists for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar dicarboxylic acid with two ionized carboxylates, no basic center, and very low predicted permeability. Although several high-F quinolone/acidic analogues transfer with high scores, their absorption depends on a basic amine, transporter involvement, or lipophilic balance absent in the query. The low-F anchors (lurtotecan, dronedarone, eliglustat) and the physicochemical prior outweigh the high-F analogues; predict low (<20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No data on active transport, efflux, or transporter-mediated absorption for the query.",
    "Metabolic stability and first-pass extraction are unknown.",
    "Transfer from fluoroquinolone analogues is limited by the query's extra carboxylate and lack of a basic amine."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

